-- Check how advancedbehavior links to transactions and traders
SELECT ab.trdref, COUNT(*) FROM (
    SELECT tr.trdref, ab.abhvreg 
    FROM advancedbehavior ab 
    JOIN transactionrecord tr ON ab.translink = tr.transreg
) ab GROUP BY ab.trdref LIMIT 10;

-- Check how many advancedbehavior records per trader
SELECT COUNT(DISTINCT tr.trdref), COUNT(*) FROM advancedbehavior ab 
JOIN transactionrecord tr ON ab.translink = tr.transreg;

SELECT COUNT(DISTINCT ab.trdref), COUNT(*) FROM (
    SELECT tr.trdref, ab.abhvreg 
    FROM advancedbehavior ab 
    JOIN transactionrecord tr ON ab.translink = tr.transreg
) ab;

SELECT trdref, COUNT(*) as cnt FROM (
    SELECT tr.trdref, ab.abhvreg 
    FROM advancedbehavior ab 
    JOIN transactionrecord tr ON ab.translink = tr.transreg
) t GROUP BY trdref HAVING COUNT(*) > 1 LIMIT 5;

